-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 creatures are in' AS assertion, count(*) AS got, 2 AS want
  FROM creatures WHERE slug IN ('dark-priest', 'host');
SELECT 'and 0 of them are playable' AS assertion, count(*) AS got, 0 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('dark-priest', 'host');
SELECT 'the creatures carry 6 attacks' AS assertion, count(*) AS got, 6 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('dark-priest', 'host');

